var S = window.SugarCube;
var setup = S.setup;
var errs = (window.__phoneErrs||[]);
return JSON.stringify({
  passage: S.State.passage,
  phone_enabled: !!setup.phone_enabled,
  has_check: typeof setup.checkPhoneConversations==='function',
  has_notify: typeof setup._notifyPhoneDelivery==='function',
  has_openphone: typeof setup.openPhone==='function',
  convs: (setup.phone_data&&setup.phone_data.conversations||[]).length,
  topics: (setup.phone_data&&setup.phone_data.daily_topics||[]).length
});

var S=window.SugarCube; var setup=S.setup; var st=S.State;
// jump into a gameplay passage so $game_state exists, then open a chat thread
try {
  // find an NPC slug that has a conversation
  var convs=(setup.phone_data.conversations||[]);
  var npc = convs.length? convs[0].npc : null;
  var app = convs.length? convs[0].app : 'messages';
  // ensure phone state container
  var sv=st.variables;
  if(!sv.game_state) sv.game_state={};
  if(!sv.game_state.phone) sv.game_state.phone={triggered_conversations:{},read_conversations:{},replies:{},triggered_posts:{},viewed_feed:false,triggered_profiles:{},liked_profiles:{},passed_profiles:{},matches:{}};
  if(!sv.game_state.time_state) sv.game_state.time_state={day:1,current_hour:9};
  // mark the first conversation triggered so the thread renders
  sv.game_state.phone.triggered_conversations[convs[0].id]={triggered_day:1,triggered_hour:9,conv_index:0};
  // build the phone overlay + open the chat thread (exercises G3 render path)
  setup.openPhone();
  setup.openChatThread(app, npc);
  var screenTxt = (document.querySelector('.phone-chat-messages')||{}).textContent || '(no chat el)';
  return JSON.stringify({npc:npc, app:app, threadRendered: !!document.querySelector('.phone-chat-messages'), sampleLen: screenTxt.length});
} catch(e) { return JSON.stringify({error: String(e)}); }

var S=window.SugarCube; var setup=S.setup; var sv=S.State.variables;
try {
  // G1a: toast helper appends a .phone-notify node
  jQuery('.phone-notify').remove();
  setup._notifyPhoneDelivery(['Frank texted you']);
  var toastShown = jQuery('.phone-notify').length > 0;
  var toastTxt = (jQuery('.phone-notify').text()||'');
  // G1b: checkPhoneConversations runs clean (baseline scan) + sets _phone_scanned
  sv.game_state.phone._phone_scanned = false;
  sv.game_state.phone.triggered_conversations = {};
  setup.checkPhoneConversations();          // first = baseline (no toast)
  var scanned = !!sv.game_state.phone._phone_scanned;
  var trigCount = Object.keys(sv.game_state.phone.triggered_conversations||{}).length;
  return JSON.stringify({toastShown:toastShown, toastTxt:toastTxt, scanned:scanned, trigCountAfterBaseline:trigCount});
} catch(e){ return JSON.stringify({error:String(e)}); }
